<?php

declare(strict_types=1);

namespace CambodiaGeo\Tests;

use CambodiaGeo\Geo;
use CambodiaGeo\GeoRecord;
use PHPUnit\Framework\TestCase;

/** Runs spec/conformance.json: results generated by the reference (Python) implementation. */
final class ConformanceTest extends TestCase
{
    /** @return array<string, mixed> */
    private static function load(): array
    {
        return json_decode((string) file_get_contents(__DIR__ . '/../spec/conformance.json'), true, 512, JSON_THROW_ON_ERROR);
    }

    public function testWasGeneratedFromTheSameDataYear(): void
    {
        self::assertSame(Geo::DATA_YEAR, self::load()['data_year']);
    }

    public function testAllCases(): void
    {
        $cases = self::load()['cases'];
        self::assertGreaterThan(50, count($cases));

        foreach ($cases as $case) {
            $title = $case['fn'] . '(' . json_encode($case['args'], JSON_UNESCAPED_UNICODE) . ', '
                . json_encode($case['kwargs'], JSON_UNESCAPED_UNICODE) . ')';

            if (isset($case['raises'])) {
                try {
                    self::call($case['fn'], $case['args'], $case['kwargs']);
                    self::fail("expected an exception: {$title}");
                } catch (\InvalidArgumentException) {
                    self::addToAssertionCount(1);
                }
                continue;
            }

            $actual = self::plain(self::call($case['fn'], $case['args'], $case['kwargs']), $case['fn'] === 'search');
            if (isset($case['expect_len'])) {
                self::assertCount($case['expect_len'], $actual, $title);
            } else {
                self::assertEquals($case['expect'], $actual, $title);
            }
        }
    }

    /**
     * @param list<mixed>         $args
     * @param array<string,mixed> $kw
     */
    private static function call(string $fn, array $args, array $kw): mixed
    {
        return match ($fn) {
            'provinces' => Geo::provinces(),
            'districts' => Geo::districts($args[0]),
            'communes' => Geo::communes($args[0], $args[1]),
            'villages' => Geo::villages($args[0], $args[1], $args[2]),
            'get_province' => Geo::getProvince($args[0]),
            'get_district' => Geo::getDistrict($args[0], province: $kw['province'] ?? null),
            'get_commune' => Geo::getCommune($args[0], district: $kw['district'] ?? null, province: $kw['province'] ?? null),
            'get_village' => Geo::getVillage(
                $args[0],
                commune: $kw['commune'] ?? null,
                district: $kw['district'] ?? null,
                province: $kw['province'] ?? null,
            ),
            'search' => array_key_exists('limit', $kw)
                ? Geo::search($args[0], $kw['level'] ?? null, $kw['limit'])
                : Geo::search($args[0], $kw['level'] ?? null),
            default => throw new \LogicException("unknown function {$fn}"),
        };
    }

    private static function plain(mixed $value, bool $withLevel): mixed
    {
        if ($value === null) {
            return null;
        }
        if (is_array($value)) {
            return array_map(static fn ($v) => self::plain($v, $withLevel), $value);
        }
        /** @var GeoRecord $value */
        return $withLevel ? ['level' => $value->level()->value] + $value->toArray() : $value->toArray();
    }
}
